@rule("s41", "s14", otherwise="NotMentioned")
def query_result():
    return "Contradiction" if "reverse engineer" in "Receiving Party shall not reverse engineer any objects which embody Disclosing Party's Confidential Information." else "NotMentioned"

@rule("s4", "s4", otherwise="NotMentioned")
def confidentiality_agreement_parties():
    return "UNHCR" in "the Office of the United Nations High Commissioner for Refugees" and "Bidder" in "__________________________"

@rule("s10", "s10", otherwise="NotMentioned")
def confidential_information_definition():
    return "Confidential Information" in "any data, document, specification and other information or material"

@rule("s25", "s25", otherwise="NotMentioned")
def confidential_information_return_or_destroy():
    return "returned to UNHCR" in "All Confidential Information in any form and any medium, including all copies thereof, disclosed to the Recipient shall be returned to UNHCR or destroyed"

@rule("s29", "s29", otherwise="NotMentioned")
def arbitration_dispute_resolution():
    return "arbitration in accordance with the UNCITRAL Arbitration Rules" in "Any dispute, controversy or claim between the Parties arising out of, this Agreement or the breach, termination or invalidity thereof"

query = confidentiality_agreement_parties() and confidential_information_definition() and confidential_information_return_or_destroy() and arbitration_dispute_resolution()
